<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Pay Salary</h1><p>Persist a validated employee salary payment.</p></div></header><section class="module-card"><div class="module-card__body"><form method="post" action="<?= url('/admin/salary/pay') ?>"><?= csrf_field() ?><div class="module-form-grid module-form-grid--three"><div class="module-field"><label>Employee</label><select class="module-select" name="employee_id" required><option value="">Select Employee</option><?php foreach($employees as$e):?><option value="<?= $e['id'] ?>"><?= e($e['employee_no'].' — '.$e['name'].' ('.number_format((float)$e['monthly_salary'],2).')') ?></option><?php endforeach ?></select></div><div class="module-field"><label>Salary Month</label><input class="module-input" type="month" name="salary_month" value="<?= date('Y-m') ?>" required></div><div class="module-field"><label>Payment Date</label><input class="module-input" type="date" name="payment_date" value="<?= date('Y-m-d') ?>" required></div><div class="module-field"><label>Paid Amount</label><input class="module-input" type="number" min="0.01" step="0.01" name="paid_amount" required></div><div class="module-field"><label>Adjustment</label><input class="module-input" type="number" step="0.01" name="adjustment_amount" value="0"></div><div class="module-field"><label>Reference</label><input class="module-input" name="reference"></div><div class="module-field field--wide"><label>Remarks</label><textarea class="module-textarea" name="remarks"></textarea></div></div><button class="btn btn--primary">Pay Salary</button></form></div></section><section class="module-card"><header class="module-card__header"><h2>Recent Payments</h2></header><div class="module-card__body"><table class="data-table"><thead><tr><th>Employee</th><th>Month</th><th>Amount</th><th>Date</th><th>Slip</th></tr></thead><tbody><?php foreach($payments as$p):?><tr><td><?= e($p['name']) ?></td><td><?= e($p['salary_month']) ?></td><td><?= number_format((float)$p['paid_amount'],2) ?></td><td><?= e($p['payment_date']) ?></td><td><a href="<?= url('/admin/salary/receipt/'.$p['id']) ?>">View</a></td></tr><?php endforeach ?></tbody></table></div></section></div></div></main>
